package com.example.examplemod.community;
import com.example.examplemod.city.*;
import com.example.examplemod.projects.*;
import com.example.examplemod.economy.EconomyManager;
import com.example.examplemod.auth.PlayerNames;
import com.example.examplemod.network.*;
import net.minecraft.nbt.*;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.neoforge.event.tick.ServerTickEvent;
import net.neoforged.neoforge.event.server.ServerStoppedEvent;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
import net.neoforged.neoforge.network.PacketDistributor;
import java.util.*;

@EventBusSubscriber(modid="createcityexpansioncore")
public final class ProjectWorkspaceService {
    private record Presence(UUID project,boolean cursor,int x,int z,long until){}
    private static final Map<MinecraftServer,Map<UUID,Presence>> PRESENCE=new WeakHashMap<>();
    private static final Map<MinecraftServer,Long> POLL=new WeakHashMap<>();
    private ProjectWorkspaceService(){}
    public static boolean participant(Project project,ProjectManager.Actor actor){
        if(project.scope()==Project.Scope.CITY)return Objects.equals(project.city(),actor.city());
        if(actor.op()||project.author().equals(actor.player()))return true;
        return project.applicants().stream().anyMatch(a->a.representative().equals(actor.player())&&(a.kind()==Project.ApplicantKind.PLAYER||actor.representsCity().test(a.id(),actor.player())));
    }
    public static boolean inside(ProjectZone zone,int x,int z){return x>=(long)zone.minX()-64&&x<=(long)zone.maxX()+64&&z>=(long)zone.minZ()-64&&z<=(long)zone.maxZ()+64;}
    public static boolean manages(Project project,ProjectManager.Actor a){return project.scope()==Project.Scope.SERVER?a.op():project.author().equals(a.player())||a.admin()||a.reviewer();}
    public static void handle(ServerPlayer p,WorkspaceRequest r){
        if(p instanceof net.neoforged.neoforge.common.util.FakePlayer)return;long second=net.minecraft.Util.getMillis()/1000;var budget=p.getPersistentData();if(budget.getLong("CCECWorkspaceWindow")!=second){budget.putLong("CCECWorkspaceWindow",second);budget.putInt("CCECWorkspaceRequests",0);}int count=budget.getInt("CCECWorkspaceRequests");if(count>=8){var busy=new CompoundTag();busy.putUUID("Request",r.request());busy.putString("Result","busy");reply(p,busy);return;}budget.putInt("CCECWorkspaceRequests",count+1);
        var s=p.getServer();var cities=CityManager.get(s.overworld());var own=cities.getMemberCity(p.getUUID());var actor=ProjectNetworkHandlers.actor(p,cities,own);var manager=EconomyManager.get(s.overworld()).projects();var data=ProjectWorkspaceData.get(s);var out=new CompoundTag();out.putUUID("Request",r.request());out.putString("Action",r.action().name());String result="ok";
        if(r.action()==WorkspaceRequest.Action.AVAILABILITY){if((r.value()&63)==0)data.recruiting.remove(p.getUUID());else if(data.recruiting.containsKey(p.getUUID())||data.recruiting.size()<4096)data.recruiting.put(p.getUUID(),r.value()&63);else result="limit";data.setDirty();}
        out.putInt("MyInterests",data.recruiting.getOrDefault(p.getUUID(),0));
        if(r.action()==WorkspaceRequest.Action.DIRECTORY){var list=manager.all().stream().filter(project->CommunityActions.visible(project,actor)).filter(project->r.flag()?project.status().terminal():!project.status().terminal()).filter(project->r.category()==6||project.category().ordinal()==r.category()).sorted(Comparator.comparing(Project::title).thenComparing(Project::id)).toList();int page=Math.min(r.page(),Math.max(0,(list.size()-1)/16));out.putInt("Page",page);out.putInt("Total",list.size());var rows=new ListTag();for(var project:list.subList(page*16,Math.min(list.size(),page*16+16))){var t=new CompoundTag();t.putUUID("Id",project.id());t.putString("Title",project.title());t.putString("Status",project.status().name());t.putString("Scope",project.scope().name());t.putString("Category",project.category().name());t.putString("Attention",CommunityActions.attention(project,actor));t.putInt("Done",(int)project.stages().stream().filter(Project.Stage::done).count());t.putInt("Stages",project.stages().size());rows.add(t);}out.put("Rows",rows);
        }else if(r.action()==WorkspaceRequest.Action.TEAM||r.action()==WorkspaceRequest.Action.AVAILABILITY){
            var completed=manager.all().stream().filter(project->project.status()==Project.Status.COMPLETED).toList();var entries=data.recruiting.entrySet().stream().filter(e->e.getValue()!=0&&(r.category()==6||(e.getValue()&(1<<r.category()))!=0)).sorted(Comparator.<Map.Entry<UUID,Integer>>comparingInt(e->s.getPlayerList().getPlayer(e.getKey())==null?1:0).thenComparing(e->PlayerNames.name(s,e.getKey()))).toList();int page=Math.min(r.page(),Math.max(0,(entries.size()-1)/16));out.putInt("Page",page);out.putInt("Total",entries.size());var rows=new ListTag();for(var entry:entries.subList(page*16,Math.min(entries.size(),page*16+16))){var t=new CompoundTag();UUID id=entry.getKey();t.putUUID("Id",id);t.putString("Name",PlayerNames.name(s,id));t.putInt("Interests",entry.getValue());t.putBoolean("Online",s.getPlayerList().getPlayer(id)!=null);var city=cities.getMemberCity(id);t.putString("City",city==null?"":city.getName());t.putString("Role",city==null?"":city.getMember(id).getRole().name());t.putInt("Confirmed",(int)completed.stream().filter(project->CommunityActions.contributor(project,id)&&(r.category()==6||project.category().ordinal()==r.category())).count());rows.add(t);}out.put("Rows",rows);
        }else{
            var project=r.project()==null?null:manager.get(r.project());if(project==null||!CommunityActions.visible(project,actor)){out.putString("Result","permission");reply(p,out);return;}
            boolean discuss=participant(project,actor),manage=manages(project,actor);var room=data.rooms.get(project.id());
            if(r.action()==WorkspaceRequest.Action.PROJECT){try{String[] parts=r.text().split("\n",2);var action=ProjectManager.Action.valueOf(parts[0]);if(!Set.of(ProjectManager.Action.APPLY,ProjectManager.Action.APPLY_CITY,ProjectManager.Action.ASSIGN,ProjectManager.Action.ASSIGN_CITY,ProjectManager.Action.STAGE,ProjectManager.Action.SUBMIT,ProjectManager.Action.APPROVE,ProjectManager.Action.ACCEPT,ProjectManager.Action.RETURN).contains(action))result="permission";else result=manager.execute(actor,new ProjectManager.Command(r.request(),project.id(),r.revision(),action,r.target(),r.value(),r.flag(),parts.length>1?parts[1]:"",null));}catch(IllegalArgumentException e){result="invalid";}project=manager.get(project.id());discuss=participant(project,actor);manage=manages(project,actor);}
            else if(r.action()!=WorkspaceRequest.Action.VIEW){
                if(!discuss||project.status().terminal())result="permission";
                else {room=data.room(project.id());if(room.receipts.contains(r.request()))result="ok";
                    else if(r.action()==WorkspaceRequest.Action.CHAT){long now=net.minecraft.Util.getMillis();if(now<budget.getLong("CCECWorkspaceChatAfter")&&budget.getLong("CCECWorkspaceChatAfter")-now<=700)result="busy";else if(r.text().isBlank()||r.text().chars().anyMatch(c->Character.isISOControl(c)||c==167))result="invalid";else {room.chat.add(new ProjectWorkspaceData.Message(r.request(),p.getUUID(),PlayerNames.name(p),r.text().strip(),System.currentTimeMillis()));while(room.chat.size()>100)room.chat.removeFirst();data.receipt(room,r.request());budget.putLong("CCECWorkspaceChatAfter",now+700);}}
                    else if(room.revision!=r.roomRevision())result="stale";
                    else if(r.action()==WorkspaceRequest.Action.MARK){if(room.marks.size()>=64)result="limit";else if(r.text().isBlank()||r.text().length()>96||r.text().chars().anyMatch(c->Character.isISOControl(c)||c==167)||!inside(project.zone(),r.x1(),r.z1())||!inside(project.zone(),r.x2(),r.z2()))result="invalid";else{room.marks.put(r.request(),new ProjectWorkspaceData.Mark(r.request(),p.getUUID(),r.text().strip(),r.x1(),r.z1(),r.x2(),r.z2(),false));data.receipt(room,r.request());}}
                    else {var mark=room.marks.get(r.target());if(mark==null)result="missing";else if(r.action()==WorkspaceRequest.Action.APPROVE_MARK&&manage){room.marks.put(mark.id(),new ProjectWorkspaceData.Mark(mark.id(),mark.author(),mark.text(),mark.x1(),mark.z1(),mark.x2(),mark.z2(),r.flag()));data.receipt(room,r.request());}else if(r.action()==WorkspaceRequest.Action.REMOVE_MARK&&(manage||mark.author().equals(p.getUUID()))){room.marks.remove(mark.id());data.receipt(room,r.request());}else result="permission";}
                }
            }
            var conflicts=new ListTag();if(manage&&project.scope()==Project.Scope.SERVER)project.zone().plots().stream().map(cities::getClaimOwner).filter(Objects::nonNull).map(City::getName).distinct().sorted().forEach(name->conflicts.add(StringTag.valueOf(name)));out.put("Conflicts",conflicts);
            out.putUUID("ProjectId",project.id());out.put("Project",ProjectCodec.write(project));out.putBoolean("CanDiscuss",discuss);out.putBoolean("CanManage",manage);out.putBoolean("CanApplyCity",own!=null&&actor.representsCity().test(own.getId(),p.getUUID()));out.putBoolean("CanFinance",actor.finance()&&project.status()==Project.Status.PENDING_FUNDING);out.putBoolean("CanReview",manage&&project.status()==Project.Status.REVIEW&&(project.executor()==null||!project.executor().representative().equals(p.getUUID())));out.putBoolean("Executor",project.executor()!=null&&project.executor().representative().equals(p.getUUID()));out.putString("Attention",CommunityActions.attention(project,actor));
            var names=new CompoundTag();names.putString(project.author().toString(),PlayerNames.name(s,project.author()));if(project.executor()!=null)names.putString(project.executor().representative().toString(),PlayerNames.name(s,project.executor().representative()));for(var a:project.applicants())names.putString(a.representative().toString(),PlayerNames.name(s,a.representative()));out.put("Names",names);
            var trace=manager.journal().trace(project.id());if(trace!=null){out.putLong("Created",trace.created);out.putLong("Completed",trace.completed);if(trace.acceptedBy!=null){out.putUUID("AcceptedBy",trace.acceptedBy);names.putString(trace.acceptedBy.toString(),PlayerNames.name(s,trace.acceptedBy));}var events=new ListTag();for(var e:trace.events){var t=new CompoundTag();t.putUUID("Id",e.id());t.putString("Action",e.action());t.putString("Actor",PlayerNames.name(s,e.actor()));t.putLong("Time",e.time());events.add(t);}out.put("Events",events);}
            if(discuss){room=data.rooms.get(project.id());long revision=room==null?0:room.revision;out.putLong("RoomRevision",revision);boolean unchanged=revision==r.roomRevision();out.putBoolean("RoomUnchanged",unchanged);
                if(!unchanged){var chat=new ListTag();var marks=new ListTag();if(room!=null){for(var m:room.chat){var t=new CompoundTag();t.putUUID("Id",m.id());t.putUUID("Author",m.author());t.putString("Name",m.name());t.putString("Text",m.text());t.putLong("Time",m.time());chat.add(t);}for(var m:room.marks.values()){var t=new CompoundTag();t.putUUID("Id",m.id());t.putUUID("Author",m.author());t.putString("Text",m.text());t.putInt("X1",m.x1());t.putInt("Z1",m.z1());t.putInt("X2",m.x2());t.putInt("Z2",m.z2());t.putBoolean("Approved",m.approved());marks.add(t);}}out.put("Chat",chat);out.put("Marks",marks);}
                var peers=PRESENCE.computeIfAbsent(s,k->new HashMap<>());long now=net.minecraft.Util.getMillis();peers.entrySet().removeIf(e->e.getValue().until<now||s.getPlayerList().getPlayer(e.getKey())==null);boolean cursor=r.flag()&&r.action()==WorkspaceRequest.Action.VIEW&&inside(project.zone(),r.x1(),r.z1());peers.put(p.getUUID(),new Presence(project.id(),cursor,r.x1(),r.z1(),now+4500));var presence=new ListTag();for(var entry:peers.entrySet())if(presence.size()<16&&entry.getValue().project.equals(project.id())){var online=s.getPlayerList().getPlayer(entry.getKey());if(online==null)continue;var memberCity=cities.getMemberCity(entry.getKey());if(!participant(project,ProjectNetworkHandlers.actor(online,cities,memberCity)))continue;var t=new CompoundTag();t.putUUID("Id",entry.getKey());t.putString("Name",PlayerNames.name(s,entry.getKey()));t.putBoolean("Cursor",entry.getValue().cursor);if(entry.getValue().cursor){t.putInt("X",entry.getValue().x);t.putInt("Z",entry.getValue().z);}presence.add(t);}out.put("Presence",presence);
            }else PRESENCE.computeIfAbsent(s,k->new HashMap<>()).remove(p.getUUID());
        }
        out.putString("Result",result);reply(p,out);
    }
    private static void reply(ServerPlayer player,CompoundTag out){PacketDistributor.sendToPlayer(player,new WorkspaceState(out));}
    @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent e){if(e.getEntity() instanceof ServerPlayer p){var peers=PRESENCE.get(p.getServer());if(peers!=null)peers.remove(p.getUUID());}}
    @SubscribeEvent public static void stopped(ServerStoppedEvent e){PRESENCE.remove(e.getServer());POLL.remove(e.getServer());}
    @SubscribeEvent public static void events(ServerTickEvent.Post e){var s=e.getServer();long now=net.minecraft.Util.getMillis();if(now<POLL.getOrDefault(s,0L))return;POLL.put(s,now+1000);var economy=EconomyManager.get(s.overworld());var manager=economy.projects();var cities=CityManager.get(s.overworld());for(var project:manager.all()){var trace=manager.journal().trace(project.id());if(trace==null||trace.events.isEmpty())continue;var event=trace.events.getLast();if(trace.announced>=event.revision())continue;if(Set.of("PUBLISH","APPROVE","APPLY","APPLY_CITY","ASSIGN","ASSIGN_CITY","SUBMIT","RETURN","ACCEPT","CANCEL").contains(event.action())){
            var recipients=new HashSet<UUID>();recipients.add(project.author());if(project.executor()!=null)recipients.add(project.executor().representative());if(project.scope()==Project.Scope.CITY){var city=cities.getCity(project.city());if(city!=null)for(var member:city.getMembers())if(project.status()==Project.Status.PENDING_FUNDING?CityAuthority.finance(city,member.getPlayerId()):CityAuthority.review(city,member.getPlayerId()))recipients.add(member.getPlayerId());}
            for(UUID owner:recipients)if(project.scope()==Project.Scope.SERVER||Objects.equals(cities.getMemberCity(owner)==null?null:cities.getMemberCity(owner).getId(),project.city()))CommunityInbox.get(s).addProject(owner,event.id(),project.id(),event.actor(),project.title());
        }trace.announced=event.revision();economy.setDirty();}}
}
